import{_ as s,o as t,c,a5 as i}from"./chunks/framework.a5no_H3L.js";const o=JSON.parse('{"title":"C# 异步：为什么需要异步","description":"本页回答三个问题：同步代码在 I/O 等待时浪费了什么，异步如何不阻塞线程，异步与并行有什么区别。这是理解 Task 与 async/await 的前提。","frontmatter":{"type":"explanation","level":"intermediate"},"headers":[],"relativePath":"csharp/03-csharp-concurrency/chapter-01-why-async.md","filePath":"csharp/03-csharp-concurrency/chapter-01-why-async.md"}'),e={name:"csharp/03-csharp-concurrency/chapter-01-why-async.md"};function r(n,a,h,l,p,d){return t(),c("div",null,[...a[0]||(a[0]=[i(`<h1 id="c-异步-为什么需要异步" tabindex="-1" data-src-line="2" data-src-file="csharp/03-csharp-concurrency/chapter-01-why-async.md">C# 异步：为什么需要异步 <a class="header-anchor" href="#c-异步-为什么需要异步" aria-label="Permalink to &quot;C# 异步：为什么需要异步&quot;">​</a></h1><p data-src-line="4" data-src-file="csharp/03-csharp-concurrency/chapter-01-why-async.md">本页回答三个问题：同步代码在 I/O 等待时浪费了什么，异步如何不阻塞线程，异步与并行有什么区别。这是理解 <code>Task</code> 与 <code>async/await</code> 的前提。</p><h2 id="_1-同步代码的问题" tabindex="-1" data-src-line="6" data-src-file="csharp/03-csharp-concurrency/chapter-01-why-async.md">1. 同步代码的问题 <a class="header-anchor" href="#_1-同步代码的问题" aria-label="Permalink to &quot;1. 同步代码的问题&quot;">​</a></h2><p data-src-line="8" data-src-file="csharp/03-csharp-concurrency/chapter-01-why-async.md">同步代码在调用 I/O 时阻塞当前线程，直到 I/O 完成。以读文件为例：</p><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">string</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> content</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> File.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ReadAllText</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;large.txt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 阻塞当前线程直到读完</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">WriteLine</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(content);</span></span></code></pre></div><p data-src-line="15" data-src-file="csharp/03-csharp-concurrency/chapter-01-why-async.md"><code>ReadAllText</code> 期间，当前线程什么都不做，只是等待磁盘返回数据。在 Web 服务里，一个线程通常对应一个请求；线程被阻塞时，新的请求就需要新的线程。当并发请求数超过线程数时，线程池会创建更多线程，但线程有内存和调度成本，且每线程固定占用约 1MB 栈空间——线程数无法无限增长。</p><p data-src-line="17" data-src-file="csharp/03-csharp-concurrency/chapter-01-why-async.md">结果是：<strong>大量时间花在「等待」上，而不是「计算」上</strong>。I/O 的耗时远大于 CPU 处理耗时，同步模型让稀缺的线程资源空转。</p><h2 id="_2-异步如何解决" tabindex="-1" data-src-line="19" data-src-file="csharp/03-csharp-concurrency/chapter-01-why-async.md">2. 异步如何解决 <a class="header-anchor" href="#_2-异步如何解决" aria-label="Permalink to &quot;2. 异步如何解决&quot;">​</a></h2><p data-src-line="21" data-src-file="csharp/03-csharp-concurrency/chapter-01-why-async.md">异步模型把「发起 I/O」和「等待完成」分开。发起 I/O 后线程可以去做别的事，I/O 完成时再回来处理结果：</p><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">string</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> content</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> File.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ReadAllTextAsync</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;large.txt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 等待期间线程可复用</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">WriteLine</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(content);</span></span></code></pre></div><p data-src-line="28" data-src-file="csharp/03-csharp-concurrency/chapter-01-why-async.md"><code>ReadAllTextAsync</code> 发起异步读取后立即返回一个 <code>Task</code>，<code>await</code> 让方法在等待期间「让出」当前线程。I/O 完成时，运行时恢复方法继续执行。关键点：<strong>等待期间不占用线程</strong>，一个线程可以服务多个并发请求。</p><p data-src-line="30" data-src-file="csharp/03-csharp-concurrency/chapter-01-why-async.md">对 I/O 密集的 Web 服务，异步能显著提升并发能力和资源利用率。一个阻塞在磁盘上的线程和一个空闲等待的线程，前者浪费了本可服务其他请求的能力。</p><h2 id="_3-异步不是并行" tabindex="-1" data-src-line="32" data-src-file="csharp/03-csharp-concurrency/chapter-01-why-async.md">3. 异步不是并行 <a class="header-anchor" href="#_3-异步不是并行" aria-label="Permalink to &quot;3. 异步不是并行&quot;">​</a></h2><p data-src-line="34" data-src-file="csharp/03-csharp-concurrency/chapter-01-why-async.md">异步和并行解决不同的问题，不要混淆：</p><table tabindex="0"><thead data-src-line="36" data-src-file="csharp/03-csharp-concurrency/chapter-01-why-async.md"><tr data-src-line="36" data-src-file="csharp/03-csharp-concurrency/chapter-01-why-async.md"><th style="text-align:left;"></th><th style="text-align:left;">异步（async）</th><th style="text-align:left;">并行（parallel）</th></tr></thead><tbody data-src-line="38" data-src-file="csharp/03-csharp-concurrency/chapter-01-why-async.md"><tr data-src-line="38" data-src-file="csharp/03-csharp-concurrency/chapter-01-why-async.md"><td style="text-align:left;">解决的问题</td><td style="text-align:left;">等待 I/O 时线程空转</td><td style="text-align:left;">CPU 计算任务变快</td></tr><tr data-src-line="39" data-src-file="csharp/03-csharp-concurrency/chapter-01-why-async.md"><td style="text-align:left;">手段</td><td style="text-align:left;">不阻塞线程</td><td style="text-align:left;">多核同时计算</td></tr><tr data-src-line="40" data-src-file="csharp/03-csharp-concurrency/chapter-01-why-async.md"><td style="text-align:left;">适用场景</td><td style="text-align:left;">I/O 密集（网络、磁盘）</td><td style="text-align:left;">CPU 密集（计算、图像）</td></tr></tbody></table><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 异步：等待 I/O，不阻塞线程</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> data</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> client.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">GetStringAsync</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(url);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 并行：多核同时计算</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Parallel.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">For</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">i</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> HeavyCompute</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(i));</span></span></code></pre></div><p data-src-line="50" data-src-file="csharp/03-csharp-concurrency/chapter-01-why-async.md">异步让「等待」变便宜，并行让「计算」变快。一个 CPU 密集的计算用异步不会更快——它不产生新的计算能力；它只是不阻塞线程。反过来，一个纯 I/O 等待用并行也帮不上忙。</p><h2 id="_4-异步的代价" tabindex="-1" data-src-line="52" data-src-file="csharp/03-csharp-concurrency/chapter-01-why-async.md">4. 异步的代价 <a class="header-anchor" href="#_4-异步的代价" aria-label="Permalink to &quot;4. 异步的代价&quot;">​</a></h2><p data-src-line="54" data-src-file="csharp/03-csharp-concurrency/chapter-01-why-async.md">异步不是免费的：</p><ul data-src-line="56" data-src-file="csharp/03-csharp-concurrency/chapter-01-why-async.md"><li data-src-line="56" data-src-file="csharp/03-csharp-concurrency/chapter-01-why-async.md"><strong>代码复杂度</strong>：<code>async/await</code> 展开为状态机，异常传播、取消和同步上下文的规则更复杂（见<a href="./chapter-02-task-async-await.html">Task 与 async/await</a>）。</li><li data-src-line="57" data-src-file="csharp/03-csharp-concurrency/chapter-01-why-async.md"><strong>少量分配</strong>：<code>Task</code> 和状态机带来额外分配，虽然运行时做了大量优化（值类型状态机等）。</li><li data-src-line="58" data-src-file="csharp/03-csharp-concurrency/chapter-01-why-async.md"><strong>传染性</strong>：<code>async</code> 会向上传染——调用异步方法的方法通常也要变异步。</li></ul><p data-src-line="60" data-src-file="csharp/03-csharp-concurrency/chapter-01-why-async.md">因此不要盲目把一切都变成异步。规则是：<strong>I/O 密集且需要高并发的边界用异步，CPU 密集的计算不需要异步</strong>。一个计算密集型的小工具用同步代码更简单。</p><h2 id="_5-后续阅读" tabindex="-1" data-src-line="62" data-src-file="csharp/03-csharp-concurrency/chapter-01-why-async.md">5. 后续阅读 <a class="header-anchor" href="#_5-后续阅读" aria-label="Permalink to &quot;5. 后续阅读&quot;">​</a></h2><ul data-src-line="64" data-src-file="csharp/03-csharp-concurrency/chapter-01-why-async.md"><li data-src-line="64" data-src-file="csharp/03-csharp-concurrency/chapter-01-why-async.md"><a href="./chapter-02-task-async-await.html">Task 与 async/await</a>解释异步的具体语法和机制。</li><li data-src-line="65" data-src-file="csharp/03-csharp-concurrency/chapter-01-why-async.md"><a href="./chapter-03-cancellation.html">取消</a>解释如何优雅地停止进行中的异步操作。</li><li data-src-line="66" data-src-file="csharp/03-csharp-concurrency/chapter-01-why-async.md"><a href="./chapter-04-threading-synchronization.html">线程与同步</a>解释多线程下共享状态的保护。</li><li data-src-line="67" data-src-file="csharp/03-csharp-concurrency/chapter-01-why-async.md"><a href="./chapter-05-parallel-linq.html">并行与 LINQ</a>解释 CPU 密集任务的并行化。</li></ul><blockquote data-src-line="69" data-src-file="csharp/03-csharp-concurrency/chapter-01-why-async.md"><p data-src-line="69" data-src-file="csharp/03-csharp-concurrency/chapter-01-why-async.md">本页的技术边界按 .NET 10 / C# 14 核对；<code>async/await</code> 自 C# 5 引入。官方参考：<a href="https://learn.microsoft.com/en-us/dotnet/" target="_blank" rel="noreferrer">.NET 文档</a>、<a href="https://learn.microsoft.com/en-us/dotnet/csharp/asynchronous-programming/" target="_blank" rel="noreferrer">异步编程</a>。</p></blockquote>`,24)])])}const k=s(e,[["render",r]]);export{o as __pageData,k as default};
